#!/usr/bin/env node
// bun run kit
//
// Builds the spine kit that tau-net ships (docs/reference/tau-universe.md §4) into
// packages/tau-net/src/tau_net/spine_kit/:
//
//   worker.js                 the Worker bundled by `wrangler deploy --dry-run --outdir`
//                             from the local-mode config (wrangler.example.jsonc)
//   wrangler.template.jsonc   the local-mode config for that bundle: main = "worker.js", no
//                             build step, the same bindings, Durable Object migrations, vars
//                             and crons; `tau net spine init` fills in ADDRESS and a route
//   package.template.json     the project's package.json, with Wrangler pinned
//   migrations/*.sql          only when the local config has a D1 binding
//   VERSION                   <package.json version>+<hash of the sources below>
//   README.md                 what the generated project is and how to deploy it
//
// Everything is derived from wrangler.example.jsonc, so a change of bindings there needs no
// change here. The kit is tracked in git; CI runs this script and `git diff --exit-code` on
// the kit, and tau-net's tests compare VERSION with the sources (the same hash rule as
// SOURCE_FILES and sourceHash below).

import { spawnSync } from "node:child_process";
import { createHash } from "node:crypto";
import {
  existsSync,
  mkdirSync,
  mkdtempSync,
  readdirSync,
  readFileSync,
  rmSync,
  statSync,
  writeFileSync,
} from "node:fs";
import { tmpdir } from "node:os";
import { basename, dirname, join, relative, sep } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const repo = join(root, "..", "..");
const out = join(repo, "packages", "tau-net", "src", "tau_net", "spine_kit");
const EXAMPLE = "wrangler.example.jsonc";

/** The inputs of VERSION's hash (paths relative to cloud/spine); `src/` and `migrations/`
 * are taken whole. tau-net's freshness test applies the same rule. */
const SOURCE_FILES = [
  "package.json",
  "bun.lock",
  "tsconfig.json",
  EXAMPLE,
  "scripts/kit.mjs",
];
const SOURCE_DIRS = ["src", "migrations"];

/** Keys of the example config that only matter for building from TypeScript. */
const BUILD_KEYS = [
  "$schema",
  "main",
  "build",
  "tsconfig",
  "alias",
  "define",
  "rules",
  "base_dir",
  "minify",
  "jsx_factory",
  "jsx_fragment",
  "no_bundle",
  "find_additional_modules",
  "preserve_file_names",
  "upload_source_maps",
];

const GENERATED = "Generated by cloud/spine/scripts/kit.mjs (`bun run kit`); do not edit.";

function fail(message) {
  console.error(`kit: ${message}`);
  process.exit(1);
}

/** JSONC to JSON: drops comments and trailing commas outside strings. */
function parseJsonc(text) {
  let json = "";
  for (let i = 0; i < text.length; i++) {
    const c = text[i];
    if (c === '"') {
      let j = i + 1;
      while (j < text.length && text[j] !== '"') j += text[j] === "\\" ? 2 : 1;
      json += text.slice(i, j + 1);
      i = j;
    } else if (c === "/" && text[i + 1] === "/") {
      while (i < text.length && text[i] !== "\n") i++;
      json += "\n";
    } else if (c === "/" && text[i + 1] === "*") {
      i = text.indexOf("*/", i + 2) + 1;
      if (i === 0) break;
    } else {
      json += c;
    }
  }
  return JSON.parse(json.replace(/,(\s*[}\]])/g, "$1"));
}

function walk(dir) {
  const files = [];
  if (!existsSync(join(root, dir))) return files;
  for (const entry of readdirSync(join(root, dir), { withFileTypes: true })) {
    const path = `${dir}/${entry.name}`;
    if (entry.isDirectory()) files.push(...walk(path));
    else if (entry.isFile()) files.push(path);
  }
  return files;
}

/** sha256 over a sha256sum-style manifest (`<hex>  <path>\n`, sorted by path). */
function sourceHash() {
  const paths = [...SOURCE_FILES, ...SOURCE_DIRS.flatMap((dir) => walk(dir))].sort();
  let manifest = "";
  for (const path of paths) {
    const digest = createHash("sha256").update(readFileSync(join(root, path))).digest("hex");
    manifest += `${digest}  ${path}\n`;
  }
  return createHash("sha256").update(manifest).digest("hex");
}

/** A top-level key and its value, indented like the rest of the file. */
function entry(key, value) {
  const body = JSON.stringify(value, null, 2).replace(/\n/g, "\n  ");
  return `  ${JSON.stringify(key)}: ${body}`;
}

const pkg = JSON.parse(readFileSync(join(root, "package.json"), "utf8"));
const config = parseJsonc(readFileSync(join(root, EXAMPLE), "utf8"));
const wranglerPkg = JSON.parse(
  readFileSync(join(root, "node_modules", "wrangler", "package.json"), "utf8"),
);
const wranglerVersion = wranglerPkg.version;

if (config.vars?.TAU_MODE !== "local") fail(`${EXAMPLE} is not the local-mode config`);
if (config.vars?.ADDRESS !== "") fail(`${EXAMPLE} must have an empty vars.ADDRESS`);
if (config.routes || config.route) fail(`${EXAMPLE} must not have routes`);
if (typeof config.main !== "string") fail(`${EXAMPLE} has no main`);

// 1. Bundle, exactly as `wrangler deploy` would, without uploading anything.
const build = mkdtempSync(join(tmpdir(), "tau-spine-kit-"));
try {
  const wrangler = join(root, "node_modules", "wrangler", "bin", "wrangler.js");
  const result = spawnSync(
    process.execPath,
    [wrangler, "deploy", "--dry-run", "--outdir", build, "--config", EXAMPLE],
    {
      cwd: root,
      encoding: "utf8",
      env: { ...process.env, WRANGLER_SEND_METRICS: "false", NO_COLOR: "1" },
    },
  );
  if (result.status !== 0) {
    process.stderr.write(result.stdout ?? "");
    process.stderr.write(result.stderr ?? "");
    fail(`wrangler deploy --dry-run failed (exit ${result.status})`);
  }

  const mainModule = basename(config.main).replace(/\.[cm]?[jt]sx?$/, ".js");
  const ignored = new Set([`${mainModule}.map`, "README.md"]);
  const produced = readdirSync(build, { recursive: true }).map((p) => p.split(sep).join("/"));
  const extra = produced.filter(
    (p) => p !== mainModule && !ignored.has(p) && statSync(join(build, p)).isFile(),
  );
  if (!produced.includes(mainModule)) fail(`the bundle has no ${mainModule}`);
  if (extra.length > 0) {
    // A bundle with more modules would need `find_additional_modules` and a base_dir in the
    // template; the spine has never needed one.
    fail(`the bundle has more modules than ${mainModule}: ${extra.join(", ")}`);
  }
  const bundle = readFileSync(join(build, mainModule), "utf8")
    .replace(/\n\/\/# sourceMappingURL=\S+\s*$/, "\n")
    .replace(/\s*$/, "\n");

  // 2. The kit's files.
  const hash = sourceHash();
  const version = `${pkg.version}+${hash.slice(0, 12)}`;
  const d1 = config.d1_databases ?? [];
  const migrationDirs = [...new Set(d1.map((db) => db.migrations_dir ?? "migrations"))];
  if (migrationDirs.length > 1) fail("more than one D1 migrations_dir is not supported");

  const files = new Map();
  files.set(
    "worker.js",
    `// tau spine ${version}: the Worker of cloud/spine, bundled by \`wrangler deploy --dry-run\`.\n` +
      `// ${GENERATED}\n${bundle}`,
  );

  const template = { name: config.name, main: "worker.js", no_bundle: true };
  const rest = Object.fromEntries(
    Object.entries(config).filter(([key]) => !BUILD_KEYS.includes(key) && key !== "name"),
  );
  for (const db of rest.d1_databases ?? []) {
    delete db.database_id;
    db.migrations_dir = "migrations";
  }
  for (const kv of rest.kv_namespaces ?? []) delete kv.id;
  const lines = [
    `// tau spine ${version}, local mode: the Wrangler config of the bundled Worker.`,
    `// ${GENERATED}`,
    "//",
    "// `tau net spine init` writes it as wrangler.jsonc; `tau net spine deploy` deploys it.",
    "// Storage bindings without an id are provisioned on the first deploy.",
    "{",
    `  "$schema": "node_modules/wrangler/config-schema.json",`,
    `${entry("name", template.name)},`,
    "  // The bundled Worker, uploaded as it is: no build step.",
    `${entry("main", template.main)},`,
    `${entry("no_bundle", true)},`,
    `${entry("find_additional_modules", false)},`,
  ];
  const keys = Object.keys(rest);
  keys.forEach((key, index) => {
    const last = index === keys.length - 1;
    if (key === "vars") {
      lines.push(
        "  // ADDRESS: the tau's address; empty means the request host (right for workers.dev).",
      );
    }
    lines.push(`${entry(key, rest[key])},`);
    if (key === "vars") {
      lines.push(
        "  // A custom domain (a zone on your account): `tau net spine init --address HOST` sets",
        "  // ADDRESS and replaces the next line with the route.",
        '  // "routes": [{ "pattern": "tau.example.com", "custom_domain": true }],',
      );
    }
    if (last) lines[lines.length - 1] = lines[lines.length - 1].replace(/,$/, "");
  });
  lines.push("}");
  const templateText = `${lines.join("\n")}\n`;
  const parsed = parseJsonc(templateText); // still valid
  if (parsed.vars?.ADDRESS !== "") fail("the template lost vars.ADDRESS");
  files.set("wrangler.template.jsonc", templateText);

  const migrate = d1.map((db) => `wrangler d1 migrations apply ${db.binding}`);
  files.set(
    "package.template.json",
    `${JSON.stringify(
      {
        name: config.name,
        version: pkg.version,
        private: true,
        description: `tau spine ${version}, deployed from the tau-net spine kit`,
        scripts: {
          deploy: ["wrangler deploy", ...migrate.map((m) => `${m} --remote`)].join(" && "),
          dev: [...migrate.map((m) => `${m} --local`), "wrangler dev"].join(" && "),
        },
        devDependencies: { wrangler: wranglerVersion },
        engines: wranglerPkg.engines ?? {},
      },
      null,
      2,
    )}\n`,
  );

  if (migrationDirs.length === 1) {
    const dir = migrationDirs[0];
    for (const name of readdirSync(join(root, dir)).sort()) {
      if (name.endsWith(".sql")) {
        files.set(`migrations/${name}`, readFileSync(join(root, dir, name), "utf8"));
      }
    }
  }

  files.set("VERSION", `${version}\n`);
  files.set("README.md", readme(version, d1.length > 0));

  // 3. Replace the kit directory (everything in it is generated).
  if (relative(repo, out).split(sep).join("/") !== "packages/tau-net/src/tau_net/spine_kit") {
    fail(`unexpected output directory ${out}`);
  }
  if (existsSync(out)) rmSync(out, { recursive: true });
  for (const [name, text] of files) {
    mkdirSync(dirname(join(out, name)), { recursive: true });
    writeFileSync(join(out, name), text);
  }
  const size = [...files.values()].reduce((sum, text) => sum + Buffer.byteLength(text), 0);
  console.log(
    `Wrote the spine kit ${version} (${files.size} files, ${(size / 1024).toFixed(1)} KiB, ` +
      `wrangler ${wranglerVersion}) to ${relative(repo, out)}.`,
  );
} finally {
  rmSync(build, { recursive: true, force: true });
}

function readme(version, hasD1) {
  const deploy = hasD1
    ? "bunx wrangler deploy\nbunx wrangler d1 migrations apply DB --remote\n"
    : "bunx wrangler deploy\n";
  return `<!-- ${GENERATED} -->

# tau spine

The spine of a tau (${version}): a Cloudflare Worker whose hostname is the tau's address. It
serves the tau's public card at \`/.well-known/tau.json\`, keeps the sealed envelopes other
taus send until the hub picks them up, and gives the hub its API under \`/hub/*\`. It never
decrypts anything and holds no contacts. It runs in local mode and fits the Workers Free plan.

This directory was written by \`tau net spine init\` from the kit inside the \`tau-net\` Python
package. You do not need the tau repository.

| File | What it is |
|---|---|
| \`worker.js\` | the bundled Worker; deployed as it is |
| \`wrangler.jsonc\` | its configuration (name \`tau-spine\`, bindings, cron), read by both deploy paths |
| \`package.json\` | Wrangler, pinned, for the Wrangler path |
${hasD1 ? "| `migrations/` | the D1 schema |\n" : ""}
## Deploy

Requirements: a Cloudflare account (the Free plan is enough). ${
    hasD1
      ? "This spine has a D1 database, whose migrations only Wrangler applies: deploy it with\nWrangler (below)."
      : "Nothing else: `tau net spine deploy`\ntalks to the Cloudflare API itself, so you need no Node.js, bun or Wrangler."
  }

\`\`\`sh
tau net spine deploy <this directory>
\`\`\`

The first time, it prints a link to Cloudflare's token page with the permissions the spine
needs filled in (Workers Scripts and Workers KV Storage to edit, Account Settings to read, and
Workers Routes for a custom domain) and asks for the token at a hidden prompt. It saves the
token in the hub's \`.env\` as \`CLOUDFLARE_API_TOKEN\`, uploads \`worker.js\` with the bindings,
Durable Object migrations and cron of \`wrangler.jsonc\`, creates the KV namespace, records the
account and namespace ids in \`wrangler.jsonc\`, creates \`TAU_SPINE_TOKEN\` in the hub's \`.env\`
when it is missing, sets it as the Worker's \`HUB_TOKEN\` secret, turns on the address and
writes \`TAU_SPINE_URL\`. Then, on the hub:

\`\`\`sh
tau net init --name "Alice's tau"
tau net publish
tau net status
\`\`\`

### With Wrangler instead

This needs Node.js 22 or newer. bun is optional: with \`bun\` and \`bunx\` on \`PATH\`, the
deploy uses \`bun install\` and \`bunx wrangler\`, else \`npm install\` and \`npx wrangler\`.
Wrangler runs on Node.js either way.

\`\`\`sh
bunx wrangler login              # once; without bun: npx wrangler login
tau net spine deploy <this directory> --wrangler
\`\`\`

\`tau net spine deploy --wrangler\` installs Wrangler, deploys the Worker${hasD1 ? ", applies the D1 migrations" : ""},
creates \`TAU_SPINE_TOKEN\` in the hub's \`.env\` when it is missing, sets it as the Worker's
\`HUB_TOKEN\` secret and writes \`TAU_SPINE_URL\`. By hand, the same steps are (with npm:
\`npm install\`, then \`npx\` for \`bunx\`):

\`\`\`sh
bun install
${deploy}bunx wrangler secret put HUB_TOKEN  # the hub's TAU_SPINE_TOKEN
\`\`\`

Both paths record the same Durable Object migration tags on the Worker, so either can deploy
after the other.

The first deploy provisions the storage the Worker needs in your account. The address is
\`tau-spine.<your-subdomain>.workers.dev\`, or your own domain when \`vars.ADDRESS\` and
\`routes\` are set in \`wrangler.jsonc\` (\`tau net spine init --address HOST\` does that; the
zone must be on your Cloudflare account). Contacts know your tau by its address, so choose it
before you add any.

## Update

Upgrade \`tau-net\`, run \`tau net spine init\` into a new directory, and deploy that one. The
Worker name \`tau-spine\` stays the same, so the new version replaces the old one, and
bindings without an id keep the storage the deployed Worker already uses.
`;
}
